template <typename Derived>
class SingletonBase {
public:
    static Derived& instance() {
        static Derived inst;
        return inst;
    }

protected:
    SingletonBase() = default;
};

class Logger : public SingletonBase<Logger> {
    friend class SingletonBase<Logger>;
public:
    int lines{0};
private:
    Logger() = default;
};

class Config : public SingletonBase<Config> {
    friend class SingletonBase<Config>;
public:
    int version{1};
private:
    Config() = default;
};

int demo() {
    Logger::instance().lines = 5;
    Config::instance().version = 2;
    return Logger::instance().lines + Config::instance().version
         + static_cast<int>(&Logger::instance() == &Logger::instance());
}

class MeyersSingleton {
public:
    static MeyersSingleton& instance() {
        static MeyersSingleton inst;
        return inst;
    }
    int value{0};

private:
    MeyersSingleton() = default;
};

class PointerSingleton {
public:
    static PointerSingleton* instance() {
        if (!inst_) inst_ = new PointerSingleton();
        return inst_;
    }
    int value{0};

private:
    PointerSingleton() = default;
    static inline PointerSingleton* inst_ = nullptr;
};

int demo() {
    MeyersSingleton::instance().value = 5;
    PointerSingleton::instance()->value = 7;
    return MeyersSingleton::instance().value + PointerSingleton::instance()->value;
}

